            { title: "Fighting Poverty", lines:[ { speaker:"Reporter", text:"The local community ___ hard to end poverty here.", options:["has worked","worked","has been working"], a:"has been working" }, { speaker:"Mayor", text:"Yes, we ___ a food bank two years ago.", options:["started","have started","have been starting"], a:"started" }, { speaker:"Reporter", text:"___ have you been providing free meals?", options:["How long","When","Since"], a:"How long" }, { speaker:"Mayor", text:"We have been providing them ___ the project began.", options:["since","for","in"], a:"since" }, { speaker:"Reporter", text:"That is an excellent way to ___ Zero Hunger.", options:["achieve","adopt","affect"], a:"achieve" } ] },
            { title: "The Beach Cleanup", lines:[ { speaker:"Celine", text:"Look at all this plastic! The ocean ___ our help.", options:["needs","is needing","has needed"], a:"needs" }, { speaker:"Albert", text:"We ___ garbage for three hours, and it's still dirty.", options:["have been collecting","collected","collect"], a:"have been collecting" }, { speaker:"Celine", text:"Don't give up! We ___ fifty bags today.", options:["have already filled","filled","have been filling"], a:"have already filled" }, { speaker:"Albert", text:"You're right. Every small action makes a difference ___.", options:["too","besides","furthermore"], a:"too" }, { speaker:"Celine", text:"Let's keep going. We are meeting the rest of the team ___ noon.", options:["at","in","on"], a:"at" } ] },
            { title: "Protecting Our Oceans", lines:[ { speaker:"Albert", text:"Goal 14 is Life Below Water. We ___ the beach since 8 AM.", options:["have been cleaning","are cleaning","clean"], a:"have been cleaning" }, { speaker:"Celine", text:"It is hard work, but I ___ we can save marine life.", options:["believe","am believing","believed"], a:"believe" }, { speaker:"Albert", text:"___ picking up trash, we are recording data.", options:["Besides","Furthermore","As well as"], a:"Besides" }, { speaker:"Celine", text:"The team ___ over 200 plastic bottles so far.", options:["has found","found","is finding"], a:"has found" }, { speaker:"Albert", text:"We still have a long way to ___ before we finish.", options:["go","going","went"], a:"go" } ] },
            { title: "Quality Education for All", lines:[ { speaker:"Interviewer", text:"Goal 4 promotes Quality Education. How long ___ at this school?", options:["have you been teaching","are you teaching","teach"], a:"have you been teaching" }, { speaker:"Teacher", text:"I have been teaching here ___ ten years.", options:["for","since","in"], a:"for" }, { speaker:"Interviewer", text:"I ___ education is the key to escaping poverty.", options:["know","am knowing","have known"], a:"know" }, { speaker:"Teacher", text:"Exactly. ___, it reduces inequality.", options:["Furthermore","Too","As well"], a:"Furthermore" }, { speaker:"Interviewer", text:"You have ___ a huge difference in these kids' lives.", options:["made","been making","makes"], a:"made" } ] }
